<script setup lang="ts">
import { ref, computed } from 'vue'

export interface SkillInfo {
  id: string
  name: string
  icon: string
  description: string
  active: boolean
}

export interface AgentVariant {
  id: string
  name: string
  description: string
  icon?: string
}

const props = defineProps<{
  agentName: string
  agentDescription: string
  agentIcon: string
  variantId: string
  variantName: string
  variants?: AgentVariant[]
  skills: SkillInfo[]
  temperature?: number
  maxTokens?: number
}>()

const emit = defineEmits<{
  (e: 'variant-change', variantId: string): void
  (e: 'skill-toggle', skillId: string): void
}>()

const showVariantPicker = ref(false)

const activeSkillCount = computed(() =>
  props.skills.filter(s => s.active).length
)

const currentVariant = computed(() =>
  props.variants?.find(v => v.id === props.variantId)
)

function toggleVariantPicker() {
  showVariantPicker.value = !showVariantPicker.value
}

function selectVariant(variantId: string) {
  emit('variant-change', variantId)
  showVariantPicker.value = false
}

function handleSkillToggle(skillId: string) {
  emit('skill-toggle', skillId)
}
</script>

