            class="variant-option"
            :class="{ active: v.id === variantId }"
            @click.stop="selectVariant(v.id)"
          >
            <span class="option-icon">{{ v.icon || '✨' }}</span>
            <div class="option-info">
              <span class="option-name">{{ v.name }}</span>
